package local.pitv;
import android.media.session.MediaController;import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.media.*;import android.media.session.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.regex.*;

/** Remote-friendly Spotify companion; Spotify handles account and audio playback. */
public class MusicActivity extends Activity {
 static final String SPOTIFY="com.spotify.tv.android";
 final Handler handler=new Handler();MediaController controller,browserController;android.media.browse.MediaBrowser browser;ImageView cover;TextView song,artist,album,status,previousLine,currentLine,nextLine,position;LinearLayout albumPanel;Button play;SeekBar seek;boolean active,lyricsOnly,dragging;String trackKey="";ArrayList<Line> lyrics=new ArrayList<>();int displayed=-2;long lastDiscovery;
 static class Line{final long time;final String text;Line(long t,String s){time=t;text=s;}}
 final Runnable tick=new Runnable(){public void run(){if(!active)return;update();handler.postDelayed(this,250);}};
 int dp(int n){return TvStyle.dp(this,n);}TextView text(String value,int size){return TvStyle.text(this,value,size);}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);build();}
 void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(26),dp(16),dp(26),dp(14));root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff132437,0xff171c2a,0xff263039}));setContentView(root);
  LinearLayout heading=new LinearLayout(this);TextView name=text("Music",24);heading.addView(name,new LinearLayout.LayoutParams(0,dp(40),1));button(heading,"Open Spotify",()->openSpotify());button(heading,"Playback access",()->access());button(heading,"Load lyrics",()->importLyrics());button(heading,"Lyrics view",()->{lyricsOnly=!lyricsOnly;albumPanel.setVisibility(lyricsOnly?View.GONE:View.VISIBLE);});button(heading,"Home",()->finish());root.addView(heading);
  LinearLayout content=new LinearLayout(this);LinearLayout.LayoutParams body=new LinearLayout.LayoutParams(-1,0,1);body.topMargin=dp(18);root.addView(content,body);albumPanel=new LinearLayout(this);albumPanel.setOrientation(1);albumPanel.setPadding(0,0,dp(28),0);content.addView(albumPanel,new LinearLayout.LayoutParams(0,-1,.85f));cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setBackground(TvStyle.shape(this,0xff263747,0xff435563));albumPanel.addView(cover,new LinearLayout.LayoutParams(-1,0,1));song=text("Your music, on the big screen",24);song.setMaxLines(2);song.setPadding(0,dp(14),0,dp(4));albumPanel.addView(song);artist=text("Start a song in Spotify",17);artist.setTextColor(TvStyle.CYAN);artist.setMaxLines(1);albumPanel.addView(artist);album=text("",12);album.setMaxLines(1);albumPanel.addView(album);
  LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setGravity(Gravity.CENTER_VERTICAL);panel.setPadding(dp(20),dp(14),dp(20),dp(14));panel.setBackground(TvStyle.shape(this,0x66223142,0xff394c60));content.addView(panel,new LinearLayout.LayoutParams(0,-1,1.25f));previousLine=text("",21);previousLine.setTextColor(0xff8493a3);previousLine.setMaxLines(2);currentLine=text("Sing along",32);currentLine.setTextColor(TvStyle.AMBER);currentLine.setMaxLines(4);nextLine=text("Use Spotify's Lyrics button, or load a synchronized .lrc file for this song.",20);nextLine.setTextColor(TvStyle.SILVER);nextLine.setMaxLines(3);for(TextView line:new TextView[]{previousLine,currentLine,nextLine}){line.setGravity(Gravity.CENTER);line.setPadding(0,dp(12),0,dp(12));panel.addView(line,new LinearLayout.LayoutParams(-1,-2));}
  status=text("Sign in inside Spotify using its on-screen pairing link. No password is stored by Pi TV.",12);status.setPadding(0,dp(12),0,dp(4));root.addView(status);LinearLayout timeline=new LinearLayout(this);position=text("0:00 / 0:00",12);timeline.addView(position,new LinearLayout.LayoutParams(dp(110),dp(30)));seek=new SeekBar(this);timeline.addView(seek,new LinearLayout.LayoutParams(0,dp(30),1));root.addView(timeline);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&controller!=null)controller.getTransportControls().seekTo(value);}public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onStopTrackingTouch(SeekBar s){dragging=false;}});LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);button(controls,"Previous",()->{if(controller!=null)controller.getTransportControls().skipToPrevious();});play=button(controls,"Play / Pause",()->toggle());button(controls,"Next",()->{if(controller!=null)controller.getTransportControls().skipToNext();});root.addView(controls);
 }
 Button button(LinearLayout row,String label,Runnable action){Button b=TvStyle.button(this,label,action);b.setTextSize(12);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(32));p.leftMargin=dp(7);row.addView(b,p);return b;}
 void openSpotify(){Intent i=getPackageManager().getLeanbackLaunchIntentForPackage(SPOTIFY);if(i==null)i=getPackageManager().getLaunchIntentForPackage(SPOTIFY);if(i==null)i=new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("market://details?id="+SPOTIFY));try{startActivity(i);}catch(Exception e){Toast.makeText(this,"Install Spotify for Android TV from Google Play",1).show();}}
 void access(){new AlertDialog.Builder(this).setTitle("Spotify playback access").setMessage("Android uses Notification access to let this screen see Spotify's active media session and control playback. Android grants broad notification access; Pi TV only uses Spotify media information and controls. It does not read notification messages, upload data, or access your password. Enable Pi TV Music in the next screen only if you want these controls.").setPositiveButton("Open access settings",(d,w)->{try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception e){Toast.makeText(this,"Notification access settings unavailable",1).show();}}).setNegativeButton("Cancel",null).show();}
 void connectBrowser(){if(browser!=null)return;browser=new android.media.browse.MediaBrowser(this,new ComponentName(SPOTIFY,SPOTIFY+".service.SpotifyMediaBrowseService"),new android.media.browse.MediaBrowser.ConnectionCallback(){@Override public void onConnected(){if(!active||browser==null)return;browserController=new MediaController(MusicActivity.this,browser.getSessionToken());controller=browserController;discover();update();}@Override public void onConnectionSuspended(){browserController=null;}@Override public void onConnectionFailed(){browserController=null;}},null);try{browser.connect();}catch(SecurityException e){browser.disconnect();browser=null;}}
 void discover(){try{MediaSessionManager manager=(MediaSessionManager)getSystemService(MEDIA_SESSION_SERVICE);controller=browserController;for(MediaController candidate:manager.getActiveSessions(new ComponentName(this,MusicSessionAccess.class)))if(SPOTIFY.equals(candidate.getPackageName())){controller=candidate;break;}status.setText(controller==null?"Start a song in Spotify, then return here with Home → Music.":"Spotify · controls and metadata stay on this Pi");}catch(SecurityException e){controller=null;status.setText("Open Spotify to listen. Enable Playback access for this custom now-playing screen.");}lastDiscovery=SystemClock.elapsedRealtime();}
 long playbackPosition(PlaybackState state,long duration){if(state==null)return 0;long p=state.getPosition();if(state.getState()==PlaybackState.STATE_PLAYING)p+=(long)((SystemClock.elapsedRealtime()-state.getLastPositionUpdateTime())*state.getPlaybackSpeed());return Math.max(0,duration>0?Math.min(duration,p):p);}
 void update(){if(controller==null||SystemClock.elapsedRealtime()-lastDiscovery>3000)discover();if(controller==null)return;MediaMetadata metadata=controller.getMetadata();PlaybackState state=controller.getPlaybackState();if(metadata==null)return;String title=metadata.getString(MediaMetadata.METADATA_KEY_TITLE),performer=metadata.getString(MediaMetadata.METADATA_KEY_ARTIST);String key=String.valueOf(performer)+"\n"+String.valueOf(title);if(!key.equals(trackKey)){trackKey=key;song.setText(title==null?"Spotify":title);artist.setText(performer==null?"":performer);album.setText(metadata.getString(MediaMetadata.METADATA_KEY_ALBUM));Bitmap bitmap=metadata.getBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART);if(bitmap==null)bitmap=metadata.getBitmap(MediaMetadata.METADATA_KEY_ART);cover.setImageBitmap(bitmap);loadLyrics();}long duration=metadata.getLong(MediaMetadata.METADATA_KEY_DURATION),at=playbackPosition(state,duration);position.setText(TvPlayer.format((int)at)+" / "+TvPlayer.format((int)duration));if(!dragging){seek.setMax((int)Math.max(1,duration));seek.setProgress((int)at);}play.setText(state!=null&&state.getState()==PlaybackState.STATE_PLAYING?"Pause":"Play");showLyrics(at);}
 void toggle(){if(controller==null){openSpotify();return;}PlaybackState state=controller.getPlaybackState();if(state!=null&&state.getState()==PlaybackState.STATE_PLAYING)controller.getTransportControls().pause();else controller.getTransportControls().play();}
 File lyricFile(){return new File(getFilesDir(),"lyrics-"+Integer.toHexString(trackKey.hashCode())+".lrc");}
 void importLyrics(){if(trackKey.isEmpty()){Toast.makeText(this,"Play a song and enable playback access first",1).show();return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,81);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=81||result!=RESULT_OK||data==null)return;try(InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>512*1024)throw new IOException();out.write(b,0,n);}ArrayList<Line> parsed=parseLyrics(out.toString("UTF-8"));if(parsed.isEmpty())throw new IOException();try(FileOutputStream file=new FileOutputStream(lyricFile())){file.write(out.toByteArray());}lyrics=parsed;displayed=-2;}catch(Exception e){Toast.makeText(this,"Choose a valid synchronized LRC file under 512 KB",1).show();}}
 static ArrayList<Line> parseLyrics(String raw){ArrayList<Line> result=new ArrayList<>();Pattern timestamp=Pattern.compile("\\[(\\d{1,3}):(\\d{2})(?:[.:](\\d{1,3}))?\\]");for(String line:raw.split("\\r?\\n")){Matcher m=timestamp.matcher(line);ArrayList<Long> times=new ArrayList<>();int end=0;while(m.find()){int seconds=Integer.parseInt(m.group(2));if(seconds>=60)continue;String fraction=m.group(3);long millis=fraction==null?0:Integer.parseInt((fraction+"000").substring(0,3));times.add(Long.parseLong(m.group(1))*60000+seconds*1000+millis);end=m.end();}String text=line.substring(end).trim();for(long at:times)result.add(new Line(at,text));}Collections.sort(result,(a,b)->Long.compare(a.time,b.time));return result;}
 void loadLyrics(){lyrics.clear();displayed=-2;try(FileInputStream in=new FileInputStream(lyricFile());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);lyrics=parseLyrics(out.toString("UTF-8"));}catch(Exception ignored){}}
 void showLyrics(long at){int line=-1;for(int i=0;i<lyrics.size()&&lyrics.get(i).time<=at;i++)line=i;if(line==displayed)return;displayed=line;if(lyrics.isEmpty()){previousLine.setText("");currentLine.setText("Lyrics for this song");nextLine.setText("Open Spotify for its lyrics, or load a synchronized .lrc file.");return;}previousLine.setText(line>0?lyrics.get(line-1).text:"");currentLine.setText(line>=0?lyrics.get(line).text:"♪");nextLine.setText(line+1<lyrics.size()?lyrics.get(line+1).text:"");if(TvStyle.motion(this)){currentLine.setAlpha(.4f);currentLine.animate().alpha(1).setDuration(220).start();}}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getAction()==KeyEvent.ACTION_DOWN&&controller!=null){if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE){toggle();return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_NEXT){controller.getTransportControls().skipToNext();return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PREVIOUS){controller.getTransportControls().skipToPrevious();return true;}}return super.dispatchKeyEvent(e);}
 @Override protected void onResume(){super.onResume();active=true;connectBrowser();discover();handler.removeCallbacks(tick);handler.post(tick);}
 @Override protected void onPause(){active=false;handler.removeCallbacks(tick);currentLine.animate().cancel();controller=null;browserController=null;if(browser!=null){browser.disconnect();browser=null;}super.onPause();}
}
